INSERT INTO CMS_BOARD_FILE
(
	board_idx, file_idx, server_file_name, org_file_name, file_ext_name,
	file_size, add_date, add_id
) VALUES
(
	#{board_idx}, #{file_idx}, #{SERVER_FILE_NAME}, #{ORG_FILE_NAME}, #{FILE_EXT},
	#{FILE_SIZE}, SYSDATE, #{add_id}
)

mapper.select:
SELECT BB_Code as board_seq, BB_Board as manage_idx, BB_Head as group_seq, BB_Parent as parent_seq, BB_Depth as group_step, ifnull(BB_ID, 'admin') as user_id, if(BB_Category = '0', '', concat('00',BB_category)) as category1,
BB_Name as user_name, BB_Pass as user_password, BB_Email as user_email, BB_Link1 as imsi_v_1, BB_Homepage as user_homepage, BB_Subject as title, BB_Content as content, if(BB_Notice = '1', 'Y', 'N') as NOTICE_YN, if(BB_Secret = '1', 'Y', 'N') as secret_yn, if(BB_OPEN = '1', 'Y', 'N') as delete_yn, BB_Hit as VIEW_COUNT, BB_WIP as user_ip, BB_MDate as modify_date, BB_WDate as add_date, BB_FileName as preview_img FROM wdb_board WHERE BB_Board = #{manager_seq}
ORDER BY BB_Code

SELECT
	BK_Code as board_seq,
	
	case
		${category5}
		else '0000' end category1,
	
	BK_OFile as ORG_FILE_NAME,
	BK_CFile as SERVER_FILE_NAME,
	concat_ws('-', bk_year,(if (length(bk_month) = 1, concat('0',bk_month), bk_month))) as imsi_v_1,
	BK_BName as title,
	BK_Content as content,
	if(BK_Open_Y = '0', '', BK_Open_Y) as imsi_v_2,
	if(BK_Writer = '0', '', BK_Writer) as imsi_v_3,
	if(BK_Company = '0', '', BK_Company) as imsi_v_4,
	if(bk_position = '0', '', bk_position) as imsi_v_6,
	if(bk_symbol = '0', '', bk_symbol) as imsi_v_7,
	if(bk_day = '0', '', bk_day) as imsi_v_8,
	BK_Hit as view_count,
	from_unixtime(BK_WDate, '%Y-%m-%d %H:%i:%s') as add_date,
	'N' as delete_yn,
	'N' as secret_yn,
	'admin' as user_id
FROM
	wdbook
where
	
	bk_bg_code = ${imsi_n_1}
	
	
	bk_bg_code = 1
	
ORDER BY
	Bk_Code

