mapper.select:
SELECT
	${fileColumns}
FROM
	${tableName}
WHERE
	b_num = #{board_seq}

select file_name_real as ORG_FILE_NAME,
replace(file_name_save, 'http://www.donggu-lib.kr/', '/Users/yongju/Documents/dglib2/donggu/') as SERVER_FILE_NAME from TN_SVP_BBS_ATCH_FILE
where bbs_id = #{manager_seq}
and cntent_id = #{board_seq}
order by file_id

select cntent
from TN_SVP_BBS_CNTENT_DETAIL
where bbs_id = #{manager_seq}
and cntent_id = #{board_seq}
order by SERLNO

SELECT
	BB_Code as board_seq,
	BB_Board as manager_seq,
	BB_Head as group_seq,
	BB_Parent as parent_seq,
	BB_Depth as group_step,
	if(trim(bb_id) = '', 'admin', bb_id) as user_id,
	if(BB_Category = '0', '', BB_category) as category1,
	BB_Name as user_name,
	BB_Pass as user_password,
	BB_Email as user_email,
	BB_Homepage as user_homepage,
	ifnull(BB_Subject, '제목없음') as title,
	BB_Content as content,
	if(BB_Notice = '1', 'Y', 'N') as NOTICE_YN,
	if(BB_Secret = '1', 'Y', 'N') as secret_yn,
	if(BB_OPEN = '1', 'Y', 'N') as delete_yn,
	BB_Hit as VIEW_COUNT,
	BB_WIP as user_ip,
	ifnull(from_unixtime(BB_MDate, '%Y-%m-%d %H:%i:%s'), '1970-01-01 00:00:00') as modify_date,
	ifnull(from_unixtime(BB_WDate, '%Y-%m-%d %H:%i:%s'), '1970-01-01 00:00:00') as add_date,
	if(BB_etc1 = '0', '', BB_etc1) as imsi_v_1,
	if(BB_etc2 = '0', '', BB_etc2) as imsi_v_2,
	if(BB_etc3 = '0', '', BB_etc3) as imsi_v_3,
	from_unixtime(BB_NSDate, '%Y-%m-%d') AS notice_start_date_str,
	from_unixtime(BB_NEDate, '%Y-%m-%d') AS notice_end_date_str
FROM
	wd_board
WHERE
	BB_Board = #{manager_seq}
AND BB_Lib = #{dbUser}
ORDER BY
	BB_Head, BB_Parent, bb_depth DESC
